//! Wire types for the Paid Rides API (see `PAID_RIDES_BACKEND_REQUIREMENTS.md`).
//!
//! Everything here is serialised in camelCase, money is always integer minor
//! units and timestamps are ISO-8601 UTC generated by the server.

use super::*;
use crate::vrp::models::rides::{AvailabilityStatus, RideOption, RideStatus};
use chrono::{DateTime, Utc};

// ---------------------------------------------------------------------------
// Value objects
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, utoipa::ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Money {
    pub amount_minor: i64,
    pub currency: String,
}

impl Money {
    pub fn new(amount_minor: i64, currency: &str) -> Self {
        Self {
            amount_minor,
            currency: currency.to_string(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, utoipa::ToSchema)]
pub struct LatLng {
    pub lat: f64,
    pub lng: f64,
}

impl LatLng {
    pub fn is_valid(&self) -> bool {
        self.lat.is_finite()
            && self.lng.is_finite()
            && (-90.0..=90.0).contains(&self.lat)
            && (-180.0..=180.0).contains(&self.lng)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, utoipa::ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Place {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    pub name: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub secondary: Option<String>,
    pub point: LatLng,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, utoipa::ToSchema)]
#[serde(rename_all = "lowercase")]
pub enum RouteSource {
    /// Computed by a routing engine on the road network (OSRM / Google).
    Road,
    /// Straight-line based approximation (routing engine unavailable).
    Approximate,
}

#[derive(Debug, Clone, Serialize, Deserialize, utoipa::ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct Route {
    pub points: Vec<LatLng>,
    pub distance_meters: i64,
    pub duration_seconds: i64,
    pub source: RouteSource,
}

#[derive(Debug, Clone, Serialize, Deserialize, utoipa::ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct RideOptionView {
    pub id: String,
    pub name: String,
    pub description: String,
    pub vehicle_class: String,
    pub capacity: i32,
    pub shared: bool,
}

impl From<&RideOption> for RideOptionView {
    fn from(o: &RideOption) -> Self {
        Self {
            id: o.id.clone(),
            name: o.name.clone(),
            description: o.description.clone(),
            vehicle_class: o.vehicle_class.clone(),
            capacity: o.capacity,
            shared: o.shared,
        }
    }
}

impl From<RideOption> for RideOptionView {
    fn from(o: RideOption) -> Self {
        Self {
            id: o.id,
            name: o.name,
            description: o.description,
            vehicle_class: o.vehicle_class,
            capacity: o.capacity,
            shared: o.shared,
        }
    }
}

