/// Create or replace a ride product and its pricing.
#[derive(Debug, Clone, Serialize, Deserialize, utoipa::ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct UpsertRideOptionDto {
    pub name: String,
    #[serde(default)]
    pub description: String,
    pub vehicle_class: String,
    pub eligible_vehicle_classes: Vec<String>,
    pub capacity: i32,
    #[serde(default)]
    pub shared: bool,
    #[serde(default = "default_currency")]
    pub currency: String,
    pub base_fare_minor: i64,
    pub per_km_minor: i64,
    pub per_minute_minor: i64,
    pub minimum_fare_minor: i64,
    #[serde(default)]
    pub booking_fee_minor: i64,
    #[serde(default = "default_free_waiting")]
    pub free_waiting_minutes: i32,
    #[serde(default)]
    pub waiting_per_minute_minor: i64,
    #[serde(default = "default_rounding")]
    pub rounding_minor: i64,
    #[serde(default = "default_true")]
    pub is_active: bool,
    #[serde(default)]
    pub sort_order: i32,
}

fn default_currency() -> String {
    "NGN".into()
}
fn default_free_waiting() -> i32 {
    5
}
fn default_rounding() -> i64 {
    5000
}
fn default_true() -> bool {
    true
}

pub const VEHICLE_CLASSES: [&str; 5] = ["compact", "sedan", "suv", "van", "premium"];

impl UpsertRideOptionDto {
    pub fn validate(&self) -> Result<(), String> {
        if self.name.trim().is_empty() {
            return Err("name is required".into());
        }
        let all_classes = std::iter::once(&self.vehicle_class).chain(&self.eligible_vehicle_classes);
        for c in all_classes {
            if !VEHICLE_CLASSES.contains(&c.as_str()) {
                return Err(format!(
                    "invalid vehicle class '{}', expected one of {:?}",
                    c, VEHICLE_CLASSES
                ));
            }
        }
        if self.eligible_vehicle_classes.is_empty() {
            return Err("eligibleVehicleClasses must not be empty".into());
        }
        if self.capacity < 1 {
            return Err("capacity must be at least 1".into());
        }
        let money = [
            self.base_fare_minor,
            self.per_km_minor,
            self.per_minute_minor,
            self.minimum_fare_minor,
            self.booking_fee_minor,
            self.waiting_per_minute_minor,
            self.rounding_minor,
        ];
        if money.iter().any(|m| *m < 0) {
            return Err("pricing values must not be negative".into());
        }
        if self.free_waiting_minutes < 0 {
            return Err("freeWaitingMinutes must not be negative".into());
        }
        if self.currency.len() != 3 {
            return Err("currency must be a 3-letter ISO code".into());
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, utoipa::ToSchema)]
